<style>
  * { box-sizing: border-box; }
  body, div, td, th, p {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px;
    color: #000;
    line-height: 1.4;
  }
  p { margin: 6px 0; }

  /* Fixed-layout tables — columns NEVER shift regardless of content */
  table.fixed {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    margin-bottom: 12px;
    word-wrap: break-word;
  }
  table.fixed th, table.fixed td {
    border: 1px solid #000;
    padding: 5px 7px;
    vertical-align: top;
  }
  table.fixed thead th {
    background: #f0f0f0;
    font-weight: bold;
    text-align: left;
  }
  table.fixed .right { text-align: right; }
  table.fixed .center { text-align: center; }
  .section-head {
    background: #f0f0f0;
    font-weight: bold;
    padding: 5px 8px;
    border: 1px solid #000;
    border-bottom: none;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }
  .letter-head, .print-heading { display: none !important; }

  /* ── WEB PREVIEW (Screen): Repeats on virtual paper ── */
  @media screen {
    .print-format {
      background-image: url('{{ letterhead_img }}') !important;
      background-size: 100% 297mm !important;
      background-repeat: repeat-y !important;
      background-position: top center !important;
      padding: 0 !important;
    }
    .print-bg-fixed { display: none !important; }
  }

  /* ── PRINT / PDF: Forces full-page background on EVERY physical page ── */
  @media print {
    @page { margin: 0 !important; size: A4; }
    html, body { margin: 0 !important; padding: 0 !important; }
    tr, td, th, p { page-break-inside: avoid; }
    .print-format { background: transparent !important; padding: 0 !important; }

    /* This fixed div natively stretches to fill 100% of every printed page */
    .print-bg-fixed {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background-image: url('{{ letterhead_img }}') !important;
      background-size: 100% 100% !important;
      background-repeat: no-repeat !important;
      z-index: -1;
      display: block !important;
    }
  }
</style>

